    if (n == 0) { return arr; }

    let max_val = arr[0];
    for (let i = 1; i < n; i++) {
        if (arr[i] > max_val) {
            max_val = arr[i];
        }
    }

    let exp = 1;
    while (divi(max_val, exp) > 0) {
        counting_sort_by_digit(arr, exp);
        exp = exp * 10;
    }
    return arr;
}

