Here's the Buffer Builder pattern in Hemlock:

```hemlock
// Growing buffer that doubles when full (using buffer type with buffer_ptr)
// Write "Hello, World!" as bytes, then read back

let capacity = 4;
let size = 0;
let buf = buffer(capacity);

fn buf_grow() {
    let new_cap = capacity * 2;
    let new_buf = buffer(new_cap);
    // Copy old data to new buffer
    let src = buffer_ptr(buf);
    let dst = buffer_ptr(new_buf);
    memcpy(dst, src, size);
    capacity = new_cap;
    buf = new_buf;
}

fn write_byte(b: u8) {
    if (size >= capacity) {
        buf_grow();
    }
    let p = buffer_ptr(buf);
    let slot = ptr_offset(p, size, 1);
    ptr_write_u8(slot, b);
    size++;
}

fn read_back() {
    let result = "";
    let p = buffer_ptr(buf);
    for (let i = 0; i < size; i++) {
        let slot = ptr_offset(p, i, 1);
        let b = ptr_deref_u8(slot);
        let ch = rune(b);
        result = result + ch;
    }
    return result;
}

// Write "Hello, World!" as individual bytes
let message = "Hello, World!";
let bytes = message.bytes();
for (b in bytes) {
    write_byte(b);
}

print(`wrote ${size} bytes`);
print(`capacity: ${capacity}`);

// Read back and reconstruct string
let reconstructed = read_back();
print(`reconstructed: ${reconstructed}`);

```

Here's the Deque Pointers pattern in Hemlock:

```hemlock
// Double-ended queue using alloc'd nodes
// Node layout: 4 bytes (i32 value) + 4 padding + 8 bytes (prev ptr) + 8 bytes (next ptr) = 24 bytes

let NODE_SIZE = 24;
let dq_head = null;
let dq_tail = null;
let dq_size = 0;

fn make_node(val: i32) {
    let node = alloc(NODE_SIZE);
    ptr_write_i32(node, val);
    // Zero out prev and next pointer slots
    let prev_slot = ptr_offset(node, 8, 1);
    ptr_write_i64(prev_slot, 0);
    let next_slot = ptr_offset(node, 16, 1);
    ptr_write_i64(next_slot, 0);
    return node;
}

fn node_val(node) {
    return ptr_deref_i32(node);
}

fn set_prev(node, prev) {
    let slot = ptr_offset(node, 8, 1);
    if (prev == null) {
        ptr_write_i64(slot, 0);
    } else {
        ptr_write_ptr(slot, prev);
    }
}

fn get_prev(node) {
    let slot = ptr_offset(node, 8, 1);
    let raw = ptr_deref_i64(slot);
    if (raw == 0) { return null; }
    return ptr_deref_ptr(slot);
}

fn set_next(node, nxt) {
    let slot = ptr_offset(node, 16, 1);
    if (nxt == null) {
        ptr_write_i64(slot, 0);
    } else {
        ptr_write_ptr(slot, nxt);
    }
}

fn get_next(node) {
    let slot = ptr_offset(node, 16, 1);
    let raw = ptr_deref_i64(slot);
    if (raw == 0) { return null; }
    return ptr_deref_ptr(slot);
}

fn push_front(val: i32) {
    let node = make_node(val);
    if (dq_head == null) {
        dq_head = node;
        dq_tail = node;
    } else {
        set_next(node, dq_head);
        set_prev(dq_head, node);
        dq_head = node;
    }
    dq_size++;
    print(`push_front: ${val}`);
}

fn push_back(val: i32) {
    let node = make_node(val);
    if (dq_tail == null) {
        dq_head = node;
        dq_tail = node;
    } else {
        set_prev(node, dq_tail);
        set_next(dq_tail, node);
        dq_tail = node;
    }
    dq_size++;
    print(`push_back: ${val}`);
}

fn pop_front() {
    if (dq_head == null) {
        print("deque empty");
        return null;
    }
    let node = dq_head;
    let val = node_val(node);
    let nxt = get_next(node);
    if (nxt != null) {
        set_prev(nxt, null);
    } else {
        dq_tail = null;
    }
    dq_head = nxt;
    free(node);
    dq_size--;
    print(`pop_front: ${val}`);
    return val;
}

fn pop_back() {
    if (dq_tail == null) {
        print("deque empty");
        return null;
    }
    let node = dq_tail;
    let val = node_val(node);
    let prv = get_prev(node);
    if (prv != null) {
        set_next(prv, null);
    } else {
        dq_head = null;
    }
    dq_tail = prv;
    free(node);
    dq_size--;
    print(`pop_back: ${val}`);
    return val;
}

fn print_deque() {
    write("deque:");
    let cur = dq_head;
    while (cur != null) {
        write(` ${node_val(cur)}`);
        cur = get_next(cur);
    }
    print("");
}

// Demo
push_front(1);
push_front(2);
push_back(3);
push_back(4);
print_deque();
print(`size: ${dq_size}`);

pop_front();
pop_back();
print_deque();
print(`size: ${dq_size}`);

// Clean up remaining nodes
while (dq_head != null) {
    pop_front();
}
print("deque cleared");

```

Here's the Dynamic Array pattern in Hemlock:

```hemlock
// Dynamic array that grows using realloc pattern (alloc new, copy, free old)
import { divi } from "@stdlib/math";

let capacity = 4;
let size = 0;
let data = alloc(capacity * 4); // i32 = 4 bytes

fn grow() {
    let new_cap = capacity * 2;
    let new_data = alloc(new_cap * 4);
    memcpy(new_data, data, size * 4);
    free(data);
    data = new_data;
    capacity = new_cap;
}

fn push(val: i32) {
    if (size == capacity) {
        grow();
    }
    let slot = ptr_offset(data, size, 4);
    ptr_write_i32(slot, val);
    size++;
}

fn print_all() {
    write("values:");
    for (let i = 0; i < size; i++) {
        let slot = ptr_offset(data, i, 4);
        let val = ptr_deref_i32(slot);
        write(` ${val}`);
    }
    print("");
}

for (let i = 1; i <= 10; i++) {
    push(i);
}

print(`capacity: ${capacity}`);
print_all();
free(data);

```

Here's the Manual Linked List pattern in Hemlock:

```hemlock
// Manual linked list using alloc/free
// Node layout: 4 bytes (i32 value) + 8 bytes (ptr next) = 12 bytes per node

let NODE_SIZE = 12;
let head = null;

fn push(val: i32) {
    let node = alloc(NODE_SIZE);
    ptr_write_i32(node, val);
    let next_slot = ptr_offset(node, 4, 1);
    if (head != null) {
        ptr_write_ptr(next_slot, head);
    } else {
        ptr_write_i64(next_slot, 0);
    }
    head = node;
}

fn get_next(node) {
    let next_slot = ptr_offset(node, 4, 1);
    let raw = ptr_deref_i64(next_slot);
    if (raw == 0) { return null; }
    return ptr_deref_ptr(next_slot);
}

fn traverse() {
    write("list:");
    let current = head;
    while (current != null) {
        let val = ptr_deref_i32(current);
        write(` ${val}`);
        current = get_next(current);
    }
    print("");
}

fn free_all() {
    let current = head;
    let count = 0;
    while (current != null) {
        let next = get_next(current);
        free(current);
        count++;
        current = next;
    }
    head = null;
    print(`freed ${count} nodes`);
}

push(10);
push(20);
push(30);
traverse();
free_all();

```

Here's the Memory Pool pattern in Hemlock:

```hemlock
// Fixed-size slab allocator / object pool
// Pool of 8 slots, each 8 bytes

let SLOT_SIZE = 8;
let POOL_SLOTS = 8;
let pool = alloc(SLOT_SIZE * POOL_SLOTS);
let used = [false, false, false, false, false, false, false, false];
let alloc_count = 0;

fn pool_alloc() {
    for (let i = 0; i < POOL_SLOTS; i++) {
        if (used[i] == false) {
            used[i] = true;
            alloc_count++;
            let slot = ptr_offset(pool, i, SLOT_SIZE);
            print(`alloc slot ${i}`);
            return slot;
        }
    }
    print("pool exhausted!");
    return null;
}

fn pool_free(slot_index: i32) {
    if (used[slot_index] == true) {
        used[slot_index] = false;
        alloc_count--;
        print(`freed slot ${slot_index}`);
    }
}

fn active_count() {
    let count = 0;
    for (let i = 0; i < POOL_SLOTS; i++) {
        if (used[i] == true) {
            count++;
        }
    }
    return count;
}

// Allocate 5 slots
let s0 = pool_alloc();
let s1 = pool_alloc();
let s2 = pool_alloc();
let s3 = pool_alloc();
let s4 = pool_alloc();

// Write data to them
ptr_write_i64(s0, 100);
ptr_write_i64(s1, 200);

print(`active: ${active_count()}`);

// Free 2 slots
pool_free(1);
pool_free(3);

print(`active after free: ${active_count()}`);

// Allocate 3 more (2 reuse freed slots, 1 new)
let s5 = pool_alloc();
let s6 = pool_alloc();
let s7 = pool_alloc();

print(`final active: ${active_count()}`);

free(pool);
print("pool freed");

