Here's the Reference Counting pattern in Hemlock:

```hemlock
// Manual reference counting with alloc
// Object layout: 4 bytes (i32 refcount) + 4 bytes (i32 data) = 8 bytes

let OBJ_SIZE = 8;

fn rc_new(data: i32) {
    let obj = alloc(OBJ_SIZE);
    ptr_write_i32(obj, 1); // refcount = 1
    let data_slot = ptr_offset(obj, 4, 1);
    ptr_write_i32(data_slot, data);
    print(`created obj(data=${data}, refcount=1)`);
    return obj;
}

fn rc_retain(obj) {
    let rc = ptr_deref_i32(obj);
    rc++;
    ptr_write_i32(obj, rc);
    let data_slot = ptr_offset(obj, 4, 1);
    let data = ptr_deref_i32(data_slot);
    print(`retain obj(data=${data}, refcount=${rc})`);
    return obj;
}

fn rc_release(obj) {
    let rc = ptr_deref_i32(obj);
    rc--;
    let data_slot = ptr_offset(obj, 4, 1);
    let data = ptr_deref_i32(data_slot);
    if (rc == 0) {
        print(`release obj(data=${data}, refcount=0) -> freed`);
        free(obj);
        return null;
    }
    ptr_write_i32(obj, rc);
    print(`release obj(data=${data}, refcount=${rc})`);
    return obj;
}

fn rc_get_data(obj) {
    let data_slot = ptr_offset(obj, 4, 1);
    return ptr_deref_i32(data_slot);
}

fn rc_get_count(obj) {
    return ptr_deref_i32(obj);
}

// Demo: shared ownership
print("--- create object ---");
let a = rc_new(42);

print("--- share with b ---");
let b = rc_retain(a);

print("--- share with c ---");
let c = rc_retain(a);

print(`data: ${rc_get_data(a)}, refcount: ${rc_get_count(a)}`);

print("--- release a ---");
a = rc_release(a);

print("--- release b ---");
b = rc_release(b);

print("--- release c (last ref, should free) ---");
c = rc_release(c);

```

Here's the Struct Of Arrays pattern in Hemlock:

```hemlock
// SoA layout with ptr arithmetic (parallel arrays for x, y, z coordinates)
import { sqrt } from "@stdlib/math";

let COUNT = 5;
// Three separate arrays for x, y, z (f64 = 8 bytes each)
let xs = alloc(COUNT * 8);
let ys = alloc(COUNT * 8);
let zs = alloc(COUNT * 8);

fn set_point(i: i32, x: f64, y: f64, z: f64) {
    ptr_write_f64(ptr_offset(xs, i, 8), x);
    ptr_write_f64(ptr_offset(ys, i, 8), y);
    ptr_write_f64(ptr_offset(zs, i, 8), z);
}

fn get_x(i: i32) {
    return ptr_deref_f64(ptr_offset(xs, i, 8));
}

fn get_y(i: i32) {
    return ptr_deref_f64(ptr_offset(ys, i, 8));
}

fn get_z(i: i32) {
    return ptr_deref_f64(ptr_offset(zs, i, 8));
}

fn distance(i: i32) {
    let x = get_x(i);
    let y = get_y(i);
    let z = get_z(i);
    return sqrt(x * x + y * y + z * z);
}

// Store 5 3D points
set_point(0, 1.0, 0.0, 0.0);
set_point(1, 0.0, 2.0, 0.0);
set_point(2, 0.0, 0.0, 3.0);
set_point(3, 1.0, 1.0, 1.0);
set_point(4, 3.0, 4.0, 0.0);

// Compute and print distances from origin
for (let i = 0; i < COUNT; i++) {
    let x = get_x(i);
    let y = get_y(i);
    let z = get_z(i);
    let d = distance(i);
    print(`point ${i}: (${x}, ${y}, ${z}) distance = ${d}`);
}

// Free all arrays
free(xs);
free(ys);
free(zs);
print("all arrays freed");

```

