// Value matching with OR patterns and guards
fn classify(n) {
    return match (n) {
        0 => "zero",
        1 | 2 | 3 => "small",
        x if x < 0 => "negative",
        x if x < 10 => "medium",
        x if x < 100 => "large",
        x => "huge"
    };
